87	// Delegate /setup/* to the setup sub-app.
88	// createSetupApp returns a Hono instance whose routes are relative to "/",
89	// so we strip the "/setup" prefix before forwarding.
90	app.all("/setup/*", async (c) => {
91	  const setupSub = createSetupApp(c.env);
92	  const url = new URL(c.req.url);
93	  // Strip leading "/setup" so routes inside the sub-app match against "/"
94	  url.pathname = url.pathname.replace(/^\/setup/, "") || "/";
95	  const rewritten = new Request(url.toString(), c.req.raw);
96	  return setupSub.fetch(rewritten);
97	});
