99	// Exact "/setup" (no trailing slash) — forward as "/"
100	app.all("/setup", async (c) => {
101	  const setupSub = createSetupApp(c.env);
102	  const url = new URL(c.req.url);
103	  url.pathname = "/";
104	  const rewritten = new Request(url.toString(), c.req.raw);
105	  return setupSub.fetch(rewritten);
106	});
